#!/usr/bin/env python3
"""rag_hybrid_update_v002_20260818_307.py -- deploys the current CS&P RAG
application state (commit 742d990 plus everything added since, at the
307-test working tree) onto an existing company-knowledge-search
installation on Windows. Supersedes rag_hybrid_update_v001_20260818_292.py
-- run this one instead; the v001 file should be deleted once this
succeeds.

WHAT THIS DOES
    Writes the current application-code files (embedded below as base64
    text): the original Hybrid RAG upgrade, the P0 Jan reasoning/token-
    budget fix (jan_disable_thinking default on, max_tokens default 700,
    ProviderGenerationLimitError, the one-time bounded generation-limit
    retry, reasoning-field diagnostics that never expose the reasoning
    text itself), temporal "latest progress" query handling, source
    citation de-duplication, and everything from the latest UI/UX pass:
    the ChatGPT-style 'CS&P RAG' interface (multi-turn chat history,
    sticky bottom composer, integer "thinking" timer with a pulsing-dots
    animation), per-document numbered citations rendered as compact
    superscripts with a matching numbered source list below each answer,
    a McKinsey-style conclusion-first/MECE answer prompt with executive-
    writing trailing-period cleanup, one-click Jan + EmbeddingGemma
    startup (scripts/ensure_local_services.py -- bounded-timeout health
    waits, never launches a duplicate process, never rebuilds embeddings
    unconditionally, always shows each service's own Ready/Offline state
    rather than one blanket status) wired into start.bat as the app's
    single entry point, automatic local Jan/llama-server path discovery,
    and the optional one-time Desktop-shortcut helper
    (create_desktop_shortcut.vbs). Backs up whatever it is about to
    replace into a timestamped folder first, then runs the
    application's own idempotent, additive-only schema migration
    (src.database.initialize_schema) against your EXISTING SQLite
    database so it gains the chunk_embeddings table (and Excel
    provenance columns) without losing or rewriting a single existing
    row.

WHAT THIS NEVER TOUCHES
    Company documents/PDFs/PPT/DOCX/XLSX, your existing SQLite database
    file itself (only additive ALTER TABLE / CREATE TABLE IF NOT EXISTS
    via the app's own migration code -- never deleted or replaced),
    embeddings/index data, Gemma/EmbeddingGemma GGUF files, .venv, venv,
    .git, .env, data/config.json, logs, caches, or anything not
    explicitly listed in FILES below. No corporate data, model weights,
    or machine-specific configuration are embedded in this script, and it
    makes no network calls of its own (the optional dependency-install
    step is the only thing that could reach the internet, and only for
    package names already missing from your environment).

USAGE (on the Windows machine, no Git required)
    1. Copy this single file anywhere convenient (e.g. Desktop).
    2. Run:
           py rag_hybrid_update.py
    3. It will try to find your existing company-knowledge-search folder
       automatically; if it can't, it will ask you to type the path.
    4. When it reports success, follow the "Next steps" it prints.

Standard library only. Works on Windows with Python 3.14 (and other
platforms/versions with a comparable stdlib).
"""

